# Run from the package root after 53_dat_full_fetch.R and 54b:  caffeinate -i Rscript data-raw/qa/58_pairing_study.R     (progress: data-raw/qa/out/58.log)   Saves data-raw/qa/out/pairing_study.rds
# Study of pairing rules between SPC tornadoes of 2007 to 2025 and NWS survey lines, on a fresh full-resolution fetch of the Damage Assessment Toolkit. Nothing here changes a shipped dataset or the published pairing.
# Rules (no distance cut-off in any of them):
#   R0  the published rule: 21 index-aligned points, mean distance, mutual closest, one survey line per tornado, candidates dated within one day
#   R1  each survey line goes to its nearest SPC tornado by the one-sided distance (mean distance of the line's own 21 points to the SPC line; for an SPC point track the distance from the point to the line); several lines per tornado
#   R2  R0, and every survey line that R0 leaves unpaired is attached to its one-sided nearest tornado when that tornado is already paired
#   R3  as R0, with candidates chosen by timestamp (the DAT stormdate within T hours of the SPC start time in UTC) instead of the one-day window; T = 1, 3 and 6 hours
#   R4  survey lines linked through event_id: a numeric DAT event_id equal to the NCEI event id of an event assigned to an SPC tornado in data-raw/qa/54b
# The swath of a tornado is the union of the polygons selected for each of its lines with the published filter (rated EF0 to EF5, at least 90% of the polygon within the SPC width plus 500 m of the centerline);
# each line is usable on its own as in the published rule (its swath lies within 200 m of at least 50% of its length), and the swath of a tornado is the union of the swaths of its usable lines; the tornado is usable when it has at least one usable line. These filter values are the published ones, not new.
suppressMessages({library(sf); library(dplyr)}); sf_use_s2(FALSE); options(width = 220, tigris_use_cache = TRUE)
source("data-raw/qa/helpers.R"); source("data-raw/survey/pairing_functions.R"); lg <- function(...) { m <- paste0(format(Sys.time(), "%H:%M:%S "), ...); cat(m, "\n"); cat(m, "\n", file = qa_out("58.log"), append = TRUE) }
for (f in list.files("data", pattern = "\\.rda$", full.names = TRUE)) load(f); R <- list()
dt <- function(x) as.POSIXct(as.numeric(x) / 1000, origin = "1970-01-01", tz = "UTC")
Lf <- readRDS(qa_out("dat_full_layer1.rds")); Pf <- readRDS(qa_out("dat_full_layer2.rds")); Lf$stormdate <- as.numeric(Lf$stormdate); Pf$stormdate <- as.numeric(Pf$stormdate); Lf$length <- as.numeric(Lf$length); Lf$sd <- dt(Lf$stormdate); Pf$sd <- dt(Pf$stormdate)
Lf <- Lf[!is.na(Lf$sd) & Lf$sd >= as.POSIXct("2007-01-01", tz = "UTC") & Lf$sd < as.POSIXct("2026-01-01", tz = "UTC"), ]; Pf <- Pf[!is.na(Pf$sd) & Pf$sd >= as.POSIXct("2007-01-01", tz = "UTC") & Pf$sd < as.POSIXct("2026-01-02", tz = "UTC"), ]
Lf <- Lf[!st_is_empty(Lf), ]; Pf <- Pf[!st_is_empty(Pf), ]; lg("fresh lines ", nrow(Lf), "; polygons ", nrow(Pf)); R$fresh <- c(lines = nrow(Lf), polygons = nrow(Pf))
Du <- merge_copies(Lf); yr <- as.integer(substr(tornado_tracks$tornado_id, 1, 4)); Tt <- tornado_tracks[yr >= 2007, ]; Tt$date <- as.Date(Tt$date); tt <- st_drop_geometry(Tt)
sp <- spc_paths(Tt); sv <- survey_paths(Du); sw <- swath_setup(Du, sv, Pf); lg("distinct lines ", nrow(Du), "; SPC tornadoes ", nrow(Tt))
pr <- candidate_distances(Du, Tt, sp, sv, 1); lg("candidate pairs ", nrow(pr))
pdist <- function(px, py, ax, ay, bx, by) { dx <- bx - ax; dy <- by - ay; L2 <- dx^2 + dy^2; t <- pmax(0, pmin(1, ((px - ax) * dx + (py - ay) * dy) / ifelse(L2 > 0, L2, 1))); sqrt((px - (ax + t * dx))^2 + (py - (ay + t * dy))^2) }   # px, py may be matrices (one row per pair); a zero-length segment gives t = 0
d1 <- numeric(nrow(pr)); isl <- sp$is_line[pr$k]
for (ch in split(seq_len(nrow(pr)), ceiling(seq_len(nrow(pr)) / 50000))) { i <- pr$i[ch]; k <- pr$k[ch]; ns <- n_samples
  d1[ch] <- rowMeans(pdist(sv$Sx[i, , drop = FALSE], sv$Sy[i, , drop = FALSE], sp$s5[k, 1], sp$s5[k, 2], sp$e5[k, 1], sp$e5[k, 2])) / 1000 }
pr$d1 <- ifelse(isl, d1, pr$dist_km)   # point tracks: the distance from the point to the survey line (as in the published pairing)
R0 <- mutual_closest(pr)[, c("i", "k")]; lg("R0 pairs: ", nrow(R0))
best1 <- pr %>% group_by(i) %>% slice_min(d1, n = 1, with_ties = FALSE) %>% ungroup(); R1 <- best1[, c("i", "k")]
un <- setdiff(seq_len(nrow(Du)), R0$i); R2 <- rbind(R0, best1[best1$i %in% un & best1$k %in% R0$k, c("i", "k")])
raw <- read.csv(qa_spc_csv(), stringsAsFactors = FALSE); raw <- raw[raw$sg == 1 & raw$yr >= 2007, ]; raw$id <- paste(raw$yr, raw$om, sep = "_"); spc_utc <- as.POSIXct(paste(raw$date, raw$time), tz = "UTC")[match(Tt$tornado_id, raw$id)] + 6 * 3600
pr$dh <- abs(as.numeric(difftime(Du$sd[pr$i], spc_utc[pr$k], units = "hours")))
rankrule <- function(p) { p <- p %>% group_by(i) %>% mutate(rs = rank(dist_km, ties.method = "first")) %>% ungroup() %>% group_by(k) %>% mutate(rt = rank(dist_km, ties.method = "first")) %>% ungroup(); p[p$rs == 1 & p$rt == 1, c("i", "k")] }
R3 <- lapply(c(1, 3, 6), function(h) rankrule(pr[pr$dh <= h, ])); names(R3) <- c("R3_1h", "R3_3h", "R3_6h"); R$r3_candidates <- data.frame(T_hours = c(1, 3, 6), candidate_pairs = sapply(c(1, 3, 6), function(h) sum(pr$dh <= h)), day_window_pairs = nrow(pr))
nc <- readRDS(qa_out("ncei_comparison.rds")); N <- nc$N; eid <- trimws(as.character(Du$event_id)); eid[is.na(eid)] <- ""; hit <- match(eid, as.character(N$EVENT_ID)); kk <- match(N$tornado_id[hit], Tt$tornado_id)
R4 <- data.frame(i = which(!is.na(kk)), k = kk[!is.na(kk)]); R$r4 <- c(lines_with_event_id = sum(nzchar(eid)), lines_with_numeric_id = sum(grepl("^[0-9]+$", eid)), lines_linked_to_an_spc_tornado = nrow(R4))
rules <- list(R0 = R0, R1 = R1, R2 = R2, R3_1h = R3$R3_1h, R3_3h = R3$R3_3h, R3_6h = R3$R3_6h, R4 = R4); for (nm in names(rules)) lg(nm, ": lines paired ", nrow(rules[[nm]]), "; tornadoes ", length(unique(rules[[nm]]$k)))
# ---- swaths (memoized per line and tornado) ---------------------------------------------------------------------------------------------------------------
memo <- new.env(); len_i <- as.numeric(st_length(sv$L5))
sw_pair <- function(i, k) { key <- paste(i, k); if (!is.null(memo[[key]])) return(memo[[key]]); s <- swath_of(sw, i, k, Tt$wid_yd); memo[[key]] <- s; s }
swath_of_tornado <- function(lines, k) { ss <- lapply(lines, function(i) sw_pair(i, k)); ok <- vapply(ss, function(x) !is.na(x$cover) && x$cover >= 0.5 && !is.null(x$geom), NA)   # a line is usable on its own as in the published rule (swath within 200 m of at least half of its length)
  g <- Filter(Negate(is.null), lapply(ss[ok], `[[`, "geom")); gu <- if (length(g)) st_union(do.call(c, lapply(g, function(x) st_sfc(x, crs = 5070)))) else NULL   # the swath of the tornado: the union of the swaths of its usable lines
  inside <- sum(vapply(seq_along(lines), function(j) if (is.na(ss[[j]]$cover)) 0 else ss[[j]]$cover * len_i[lines[j]], 0)); cov <- inside / sum(len_i[lines])
  list(geom = gu, cover = cov, usable = any(ok), n_usable_lines = sum(ok), n_used = sum(vapply(ss, function(s) s$n_used, 1L)), area_km2 = if (!is.null(gu)) as.numeric(st_area(gu)) / 1e6 else NA_real_) }
extent_of_chord <- function(geom, k) { if (is.null(geom) || !sp$is_line[k]) return(NA_real_); g <- st_collection_extract(st_sfc(geom[[1]], crs = 5070), "POLYGON"); xy <- st_coordinates(g)[, 1:2, drop = FALSE]; if (!nrow(xy)) return(NA_real_)
  a <- sp$s5[k, ]; b <- sp$e5[k, ]; dx <- b[1] - a[1]; dy <- b[2] - a[2]; t <- ((xy[, 1] - a[1]) * dx + (xy[, 2] - a[2]) * dy) / (dx^2 + dy^2); min(max(t), 1) - max(min(t), 0) }
summ <- function(P) { P <- P[order(P$k, P$i), ]; split_i <- split(P$i, P$k); ks <- as.integer(names(split_i)); out <- vector("list", length(ks))
  for (j in seq_along(ks)) { s <- swath_of_tornado(split_i[[j]], ks[j]); out[[j]] <- list(k = ks[j], lines = split_i[[j]], usable = s$usable, n_usable_lines = s$n_usable_lines, cover = s$cover, area_km2 = s$area_km2, n_used = s$n_used, ext = extent_of_chord(s$geom, ks[j]), geom = s$geom)
    if (j %% 2000 == 0) lg("  swaths ", j, " of ", length(ks)) }; out }
S <- list(); for (nm in names(rules)) { lg("swaths for ", nm); S[[nm]] <- summ(rules[[nm]]) }
tab <- function(L) data.frame(tornadoes = length(L), usable = sum(vapply(L, `[[`, NA, "usable")), with_more_than_one_line = sum(vapply(L, function(x) length(x$lines) > 1, NA)), with_more_than_one_usable_line = sum(vapply(L, function(x) x$n_usable_lines > 1, NA)), lines = sum(vapply(L, function(x) length(x$lines), 1L)), usable_lines = sum(vapply(L, `[[`, 1L, "n_usable_lines")))
# ---- ZCTA lists of the usable swaths and agreement with the SPC layer -------------------------------------------------------------------------------------------
Z <- lapply(c(2000, 2010, 2020), function(v) { sfx <- substr(v, 3, 4); z <- tigris::zctas(year = v, progress_bar = FALSE); z <- z[, paste0("ZCTA5CE", sfx)]; names(z)[1] <- "ZCTA"; st_make_valid(st_transform(z, 5070)) }); names(Z) <- c(2000, 2010, 2020)
ZB <- lapply(Z, function(z) t(vapply(st_geometry(z), function(g) as.numeric(st_bbox(g)), numeric(4))))   # bounding boxes, to find the candidate ZCTAs of a swath quickly
zl <- function(geom, tid) { y <- as.integer(substr(tid, 1, 4)); vn <- as.character(ifelse(y < 2010, 2000, ifelse(y < 2020, 2010, 2020))); z <- Z[[vn]]; g <- st_sfc(geom[[1]], crs = 5070); b <- as.numeric(st_bbox(g)); bb <- ZB[[vn]]
  cand <- which(bb[, 1] <= b[3] & bb[, 3] >= b[1] & bb[, 2] <= b[4] & bb[, 4] >= b[2]); if (!length(cand)) return(character(0)); h <- cand[lengths(st_intersects(z[cand, ], g)) > 0]; if (!length(h)) return(character(0))
  x <- suppressWarnings(st_intersection(st_sf(geometry = g), z[h, "ZCTA"])); x <- x[as.character(st_geometry_type(x)) %in% c("POLYGON", "MULTIPOLYGON", "GEOMETRYCOLLECTION"), ]; if (any(st_geometry_type(x) == "GEOMETRYCOLLECTION")) x <- st_collection_extract(x, "POLYGON"); a <- as.numeric(st_area(x)); unique(x$ZCTA[a > 0]) }
zmemo <- new.env(); zget <- function(x) { key <- paste(x$k, paste(x$lines, collapse = ",")); if (is.null(zmemo[[key]])) zmemo[[key]] <- if (x$usable) zl(x$geom, tt$tornado_id[x$k]) else NULL; zmemo[[key]] }
spc_z <- split(tornado_exposure$ZCTA, tornado_exposure$tornado_id)
agree <- function(L) { L <- Filter(function(x) x$usable, L); both <- mod <- sur <- 0L; same <- 0L; jac <- numeric(0); for (x in L) { a <- spc_z[[tt$tornado_id[x$k]]]; b <- zget(x); if (is.null(a)) a <- character(0); both <- both + length(intersect(a, b)); mod <- mod + length(a); sur <- sur + length(b); same <- same + setequal(a, b); jac <- c(jac, length(intersect(a, b)) / max(length(union(a, b)), 1)) }
  data.frame(usable_tornadoes = length(L), spc_zcta_rows = mod, swath_zcta_rows = sur, both = both, precision = both / mod, recall = both / sur, jaccard_rows = both / (mod + sur - both), same_zcta_list_share = same / length(L), mean_tornado_jaccard = mean(jac)) }
R$summary <- do.call(rbind, lapply(names(S), function(nm) cbind(rule = nm, tab(S[[nm]]), agree(S[[nm]])))); lg("agreement done"); print(R$summary)
ext_q <- function(L) { e <- vapply(Filter(function(x) x$usable, L), `[[`, 0, "ext"); e <- e[!is.na(e)]; c(n = length(e), quantile(e, c(0, .05, .1, .25, .5, .75, 1)), share_below_0.8 = mean(e < 0.8)) }; R$extent <- do.call(rbind, lapply(S, ext_q))
