  data.frame(rule = nm, case = cn, lines = paste(Du$objectid[x$lines], collapse = ","), usable = x$usable, extent = x$ext, zctas = if (is.null(z)) NA_integer_ else length(z), missouri_zctas = if (is.null(z)) NA_integer_ else sum(substr(z, 1, 2) %in% c("63", "64", "65")), illinois_zctas = if (is.null(z)) NA_integer_ else sum(substr(z, 1, 2) %in% c("60", "61", "62")), stringsAsFactors = FALSE) }))))
