sig <- function(x) if (!x$usable) "not usable" else paste(sort(zget(x)), collapse = " "); s0 <- setNames(lapply(S$R0, sig), tt$tornado_id[vapply(S$R0, `[[`, 1L, "k")])
R$change <- do.call(rbind, lapply(names(S)[-1], function(nm) { s1 <- setNames(lapply(S[[nm]], sig), tt$tornado_id[vapply(S[[nm]], `[[`, 1L, "k")]); all_ids <- union(names(s0), names(s1)); a <- vapply(all_ids, function(i) if (is.null(s0[[i]])) "none" else s0[[i]], ""); b <- vapply(all_ids, function(i) if (is.null(s1[[i]])) "none" else s1[[i]], "")
  data.frame(rule = nm, tornadoes_with_a_different_result = sum(a != b), became_usable = sum(a == "not usable" & b != "not usable" & b != "none"), became_usable_from_unpaired = sum(a == "none" & b != "not usable" & b != "none"), lost_usable = sum(a != "not usable" & a != "none" & (b == "not usable" | b == "none")), zcta_list_changed = sum(a != "not usable" & a != "none" & b != "not usable" & b != "none" & a != b)) }))
