  d <- d[order(-vapply(d, function(i) length(L[[match(i, ids2)]]$lines), 1L), d)]; data.frame(tornado_id = head(d, 20), lines = vapply(head(d, 20), function(i) paste(Du$objectid[L[[match(i, ids2)]]$lines], collapse = ","), ""), usable_new = vapply(head(d, 20), function(i) L[[match(i, ids2)]]$usable, NA), usable_published_rule = vapply(head(d, 20), function(i) !is.null(s0[[i]]) && s0[[i]] != "not usable", NA)) }); names(R$examples) <- names(S)[-1]
